.requirement { color: var(--muted); font-weight: 400; font-size: 13px; }
#entry-error { grid-column: 1 / -1; color: var(--red); }
#entry-error:empty { display: none; }
.new-todo[aria-invalid="true"] { border-color: var(--red); }
.toggle-all:indeterminate + label:before { content: '−'; color: white; background: #287268; }
.filters li a { min-width: 44px; justify-content: center; }
.task-actions { display: flex; align-items: center; border-radius: 6px; background: #f6f4f1; }
.task-actions button { border-radius: 5px; }
.task-actions button:focus-visible { z-index: 1; }
@media (hover: hover) {
 .task-actions button:hover { background: #eae6e1; }
}
.task-editor { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; grid-template-areas: 'field save cancel' 'hint hint hint'; gap: 5px 8px; align-items: center; }
.task-editor .edit { grid-area: field; min-width: 0; }
.edit-hint { grid-area: hint; color: var(--muted); font: 400 13px/1.4 inherit; font-family: inherit; font-size: 13px; line-height: 1.4; }
.task-editor button { min-height: 44px; padding: 0 14px; border-radius: 5px; font: inherit; font-size: 14px; font-weight: 600; }
.save-edit { grid-area: save; background: var(--red); color: white; }
.cancel-edit { grid-area: cancel; background: #f6f4f1; }
@media (max-width: 520px) {

.todo-list .view { display: flex; flex-wrap: wrap; gap: 2px 4px; padding: 6px 10px 6px 3px; }
 .todo-list li .toggle { flex: 0 0 44px; }
 .todo-list li label { flex: 1 1 auto; box-sizing: border-box; max-width: calc(100% - 48px); padding-inline: 0; font-size: 17px; }
 .task-actions { margin-left: auto; }
 .task-editor { grid-template-areas: 'field field field' 'hint save cancel'; row-gap: 8px; }
 .todo-list li.editing { padding-inline: 14px; }
